{{--
    Brand lockup (owner decision, 2026-10-23: Concept D,
    "Signature Sweep"; pack record: hidden_files/redesign/logo/
    final-d/logo-d-record.md). One component renders every
    lockup in the product. The signature is the logo: the
    "Easy Refer" wordmark (Inter 700, tracking -0.02em, paths
    outlined from the app's own Inter, so nothing depends on a
    locally installed font) underlined by the two-tone sweep
    check, descending arm in ink, rising arm in amber, meeting
    at the vertex under the wordmark. Variants: color (ink-950
    wordmark and first arm, for light grounds), reversed (white
    wordmark and first arm, for ink grounds; the standard
    signature's tile-free mark needs no ground swap, but the
    companion tile does), mono (one-color ink throughout).
    Size is the rendered height in px; the signature's width
    follows its 532.2:171 box. With wordmark=false the
    component renders the companion mark instead: the sweep's
    check redrawn bold on the ink tile (arm ratio 1:1.9, stroke
    7 on the 48 grid), for square slots and small sizes where
    the signature is a hairline (favicon duty). The companion
    follows the same variants: color (ink tile, cream first
    arm), reversed (white tile, ink first arm; the color
    companion vanishes on ink-950), mono (ink tile, white
    glyph).
--}}
@props(['variant' => 'color', 'size' => 32, 'wordmark' => true])
@php
    $signatureFills = match ($variant) {
        'reversed' => ['#FFFFFF', '#FFFFFF', '#F5A300'],
        'mono' => ['#16130E', '#16130E', '#16130E'],
        default => ['#0D0B08', '#0D0B08', '#F5A300'],
    };
    $companionFills = match ($variant) {
        'reversed' => ['#FFFFFF', '#16130E', '#F5A300'],
        'mono' => ['#16130E', '#FFFFFF', '#FFFFFF'],
        default => ['#16130E', '#FAF6EF', '#F5A300'],
    };
    $signatureWidth = (int) round($size * 532.2 / 171);
@endphp
@if ($variant === 'auto')
    {{-- Dark-mode-spec.md C-19: both lockups render inside a
         display:contents shell; the .logo-for-light and
         .logo-for-dark classes in app.css show exactly one per
         color scheme, so the mark follows the device setting
         with no JavaScript and no layout shift. --}}
    <span class="logo-auto" {{ $attributes }}>
        <span class="logo-for-light"><x-logo variant="color" :size="$size" :wordmark="$wordmark" /></span>
        <span class="logo-for-dark"><x-logo variant="reversed" :size="$size" :wordmark="$wordmark" /></span>
    </span>
@elseif ($wordmark)
